fn cohere_assign_tool_ir_index(
    state: &mut crate::ir::StreamDecodeState,
    frame_idx: usize,
) -> Option<usize> {
    // Duplicate tool-call-start for a frame already open: no-op (do not re-assign or re-emit).
    if cohere_lookup_tool_ir_index(state, frame_idx).is_some() {
        return None;
    }

let message_val = obj.get("message").ok_or(IrError {
            class: StatusClass::ClientError,
            provider_signal: Some(busbar_substrate_values::proto::SIGNAL_IR_PARSE.to_string()),
            retry_after: None,
        })?;

let raw_finish_reason = obj
            .get("finish_reason")
            .and_then(|r| r.as_str())
            .unwrap_or("");
        let stop_reason = if raw_finish_reason.is_empty() {
            None
        } else {
            Some(read_cohere_stop_reason(raw_finish_reason))
        };

if !state.open_tools.contains(&idx)
                        && !state.open_tools.contains(&(idx + TEXT_INDEX_KEY_OFFSET))
                    {
                        if state.open_tools.len() >= MAX_OPEN_TOOLS {
                            return out;
                        }
                        state.open_tools.insert(idx);
                        out.push(IrStreamEvent::BlockStart {
                            index: idx,
                            block: crate::ir::IrBlockMeta::Thinking,
                        });
                    }
                    out.push(IrStreamEvent::BlockDelta {
                        index: idx,
                        delta: crate::ir::IrDelta::ThinkingDelta(delta),
                    });

out.push(IrStreamEvent::MessageDelta {
                    stop_reason: Some(stop_reason),
                    // Gemini has no stop_sequence analog in its stream.
                    stop_sequence: None,
                    usage,
                });
                out.push(IrStreamEvent::MessageStop);

let Ok(mut data) = serde_json::from_slice::<serde_json::Value>(&payload) else {
                    continue; // non-JSON payload -- skip the frame
                };
